
// HÀM ĐỊNH DẠNG CÁC YÊU CẦU DỌC XẾP THEO THỨ TỰ DƯỚI TÊN MÓN (+ TOPPING, ĐÁ, ĐƯỜNG, GHI CHÚ)
    function formatItemCustomRequirementsHtml(c, idx) {
      const callIdx = (typeof idx === 'number') ? idx : (typeof editingCartIndex === 'number' ? editingCartIndex : 0);
      let pills = [];

      if (c.ice) {
        pills.push('<span class="ios-opt-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')" title="Chạm trực tiếp để đổi mức đá">🧊 ' + c.ice + '</span>');
      }
      if (c.sugar) {
        pills.push('<span class="ios-opt-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')" title="Chạm trực tiếp để đổi mức ngọt">🍯 ' + c.sugar + '</span>');
      }
      if (c.toppings && Array.isArray(c.toppings) && c.toppings.length > 0) {
        c.toppings.forEach(t => {
          const tName = (typeof t === 'string') ? t : t.name;
          pills.push('<span class="ios-opt-pill ios-topping-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')" title="Chạm trực tiếp để đổi topping">+ ' + tName + '</span>');
        });
      }
      if (c.note) {
        pills.push('<span class="ios-opt-pill ios-note-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')" title="Chạm trực tiếp để sửa ghi chú">📝 ' + c.note + '</span>');
      }

      if (pills.length === 0 && c.custom && c.custom !== 'Mặc định') {
        const parts = c.custom.split('•').map(p => p.trim()).filter(Boolean);
        parts.forEach(p => {
          if (p.toLowerCase().includes('topping:')) {
            const topList = p.replace(/topping:/i, '').trim().split(',').map(x => x.trim()).filter(Boolean);
            topList.forEach(t => {
              pills.push('<span class="ios-opt-pill ios-topping-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')">+ ' + t + '</span>');
            });
          } else if (p.toLowerCase().includes('đá')) {
            pills.push('<span class="ios-opt-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')">🧊 ' + p + '</span>');
          } else if (p.toLowerCase().includes('ngọt') || p.toLowerCase().includes('đường')) {
            pills.push('<span class="ios-opt-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')">🍯 ' + p + '</span>');
          } else if (p.toLowerCase().includes('ghi chú:')) {
            pills.push('<span class="ios-opt-pill ios-note-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')">' + p + '</span>');
          } else {
            pills.push('<span class="ios-opt-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')">+ ' + p + '</span>');
          }
        });
      }

      if (pills.length === 0) {
        return '<span class="ios-opt-pill" onclick="event.stopPropagation(); openEditCartItemModal(' + callIdx + ')" style="color:#636366;" title="Chạm để thêm tùy chọn">⚙️ Mặc định (Đủ đá, ngọt)</span>';
      }

      return pills.join(' ');
    }

