    // ==================== CẤU HÌNH ĐỊNH TUYẾN MÁY CHỦ CLOUD RENDER ====================
    const DEFAULT_CLOUD_SERVER_URL = 'https://mom-bd4h.onrender.com';

    function getActiveCloudServerUrl() {
      let custom = (localStorage.getItem('duynh_cloud_server_url') || '').trim();
      if (custom && (custom.includes('github.io') || custom.includes('github.com'))) {
        localStorage.removeItem('duynh_cloud_server_url');
        custom = '';
      }
      if (custom) return custom.replace(/\/+$/, '');

      // Mặc định tự động kết nối máy chủ Render trên GitHub Pages!
      if (window.location.host.includes('github.io')) {
        return DEFAULT_CLOUD_SERVER_URL;
      }
      // Nếu mở trực tiếp trên localhost hoặc Render
      if (window.location.protocol.startsWith('http')) {
        return window.location.origin;
      }
      return DEFAULT_CLOUD_SERVER_URL;
    }

    function getCloudApiUrl(path) {
      const server = getActiveCloudServerUrl();
      if (server && !window.location.origin.includes(server.replace(/^https?:\/\//, ''))) {
        return server.replace(/\/+$/, '') + path;
      }
      return path;
    }

    function getCloudWsUrl() {
      const server = getActiveCloudServerUrl();
      const wsProto = (server.startsWith('https') || window.location.protocol === 'https:') ? 'wss:' : 'ws:';
      const host = server.replace(/^https?:\/\//, '').replace(/\/+$/, '');
      return `${wsProto}//${host}/ws`;
    }

    // ==================== GLOBAL FETCH INTERCEPTOR (TỰ ĐỘNG ĐỊNH TUYẾN TẤT CẢ API SANG RENDER) ====================
    if (typeof window !== 'undefined' && window.fetch) {
      const _origFetch = window.fetch;
      window.fetch = function(resource, init) {
        if (typeof resource === 'string' && resource.startsWith('/api/')) {
          const targetUrl = getCloudApiUrl(resource);
          return _origFetch(targetUrl, init);
        }
        return _origFetch(resource, init);
      };
    }

    try {
      const urlParams = new URLSearchParams(window.location.search);
      if (urlParams.has('server')) {
        const srv = urlParams.get('server').trim();
        if (srv && !srv.includes('github.io') && !srv.includes('github.com')) {
          localStorage.setItem('duynh_cloud_server_url', srv.replace(/\/+$/, ''));
          console.log('[Cloud POS] Đã tự động cấu hình máy chủ Cloud từ URL:', srv);
        }
      }
    } catch(e) {}

        const LOCAL_DEVICE_ID = 'dev_' + Math.random().toString(36).substring(2, 9) + '_' + Date.now();
    let wsClient = null;
