    // ==================== WEBSOCKET CLIENT KẾT NỐI MÁY CHỦ RENDER ====================
    function initWebSocketSync() {
      if (typeof WebSocket === 'undefined') return;

      const wsUrl = getCloudWsUrl();
      if (!wsUrl) return;

      try {
        if (wsClient && (wsClient.readyState === 0 || wsClient.readyState === 1)) return;
        if (wsClient) try { wsClient.close(); } catch(e) {}

        wsClient = new WebSocket(wsUrl);

        wsClient.onopen = () => {
          console.log('⚡ [Render WebSocket] Đã kết nối thành công:', wsUrl);
          updateCloudSyncIndicator('🟢 Render Cloud: Live (<50ms)', true);
          if (wsReconnectTimer) {
            clearTimeout(wsReconnectTimer);
            wsReconnectTimer = null;
          }

          try {
            wsClient.send(JSON.stringify({
              type: 'REQUEST_FULL_SYNC',
              deviceId: LOCAL_DEVICE_ID,
              senderId: LOCAL_DEVICE_ID
            }));
          } catch(e) {}

          if (wsPingTimer) clearInterval(wsPingTimer);
          wsPingTimer = setInterval(() => {
            if (wsClient && wsClient.readyState === 1) {
              try { wsClient.send(JSON.stringify({ type: 'PING', timestamp: Date.now() })); } catch(e) {}
            }
          }, 15000);
        };

        wsClient.onmessage = (event) => {
          try {
            const payload = JSON.parse(event.data);
            if (payload && (payload.type || payload.action)) {
              handleIncomingMeshPayload(payload, 'render_ws');
            }
          } catch(e) {
            console.warn('[WebSocket] Lỗi đọc tin nhắn:', e);
          }
        };

        wsClient.onclose = () => {
          if (wsPingTimer) clearInterval(wsPingTimer);
          scheduleWsReconnect();
        };

        wsClient.onerror = () => {
          try { wsClient.close(); } catch(e) {}
        };
      } catch(e) {
        scheduleWsReconnect();
      }
    }

    function scheduleWsReconnect() {
      updateCloudSyncIndicator('🟡 Đang kết nối lại Render...', false);
      if (wsReconnectTimer) return;
      wsReconnectTimer = setTimeout(() => {
        wsReconnectTimer = null;
        initWebSocketSync();
      }, 3000);
    }

    // ==================== MULTI-TAB BROADCASTCHANNEL ====================
    function initLocalTabSync() {
      try {
        if (typeof BroadcastChannel !== 'undefined') {
          localTabBroadcast = new BroadcastChannel('duynh_pos_tabs_local');
          localTabBroadcast.onmessage = (event) => {
            if (event.data && typeof event.data === 'object') {
              handleIncomingMeshPayload(event.data, 'local_tab');
            }
          };
        }
      } catch(e) {}
    }

        // ==================== FAST HTTP POLLING TỪ RENDER (CÓ DIFFING CHỐNG LAG) ====================
    async function pullFullSyncFromServer() {
      // Nếu WebSocket đang kết nối trực tiếp, không cần gọi HTTP polling dồn dập
      if (wsClient && wsClient.readyState === 1 && isInitialLoadDone) {
        return;
      }

      let syncUrl = getCloudApiUrl('/api/sync');
      if (!syncUrl) return;

      // Gửi kèm version hiện tại để server trả về 50 bytes nếu không có thay đổi
      if (lastMenuVersion && lastOrdersVersion) {
        syncUrl += (syncUrl.includes('?') ? '&' : '?') + 
          `mv=${lastMenuVersion}&ov=${lastOrdersVersion}&cv=${lastConfigVersion || 0}&dv=${lastDiscountsVersion || 0}`;
      }

      const startTime = Date.now();
      try {
        const resp = await fetch(syncUrl, { cache: 'no-store' });
        if (resp.ok) {
          const data = await resp.json();
          const latency = Date.now() - startTime;

          // Nếu server báo dữ liệu không đổi (notModified), không làm gì cả -> 0% CPU lag!
          if (data && data.notModified === true) {
            if (!wsClient || wsClient.readyState !== 1) {
              updateCloudSyncIndicator(`🟢 Render: Live (${latency}ms)`, true);
            }
            return;
          }

          if (data && (Array.isArray(data.orders) || Array.isArray(data.menu))) {
            handleIncomingMeshPayload({
              type: 'FULL_SYNC',
              orders: data.orders,
              menu: data.menu,
              discounts: data.discounts,
              config: data.config,
              codeVersion: data.codeVersion,
              menuVersion: data.menuVersion,
              ordersVersion: data.ordersVersion,
              configVersion: data.configVersion,
              discountsVersion: data.discountsVersion
            }, 'render_http');
            isInitialLoadDone = true;
          }

          if (!wsClient || wsClient.readyState !== 1) {
            updateCloudSyncIndicator(`🟢 Render: Live (${latency}ms)`, true);
          }
        }
      } catch(e) {
        // Render đang khởi động hoặc ngủ đông
      }
    }

    // ==================== XỬ LÝ DỮ LIỆU ĐỒNG BỘ ĐẾN ====================
    function handleIncomingMeshPayload(payload, source = 'cloud') {
      if (!payload || typeof payload !== 'object') return;
      if (payload.senderId && payload.senderId === LOCAL_DEVICE_ID) return;

      const type = payload.type || payload.action;
      let stateChanged = false;

      switch (type) {
        case 'NEW_ORDER': {
          const newOrder = payload.order || payload.data;
          if (newOrder && newOrder.id) {
            const exIdx = orders.findIndex(o => o.id === newOrder.id);
            if (exIdx === -1) {
              orders.unshift(newOrder);
              stateChanged = true;
              playNewOrderAlertSound();
              showSmsToast("☁️ ĐƠN MỚI TỪ KHÁCH!", `Đơn #${newOrder.id} (${newOrder.customerName || 'Khách'}) vừa đặt qua Render Cloud!`);
            } else {
              orders[exIdx] = { ...orders[exIdx], ...newOrder };
              stateChanged = true;
            }
          }
          if (Array.isArray(payload.menuStock)) {
            mergeMenuStock(payload.menuStock);
          }
          break;
        }

        case 'ORDER_STATUS': {
          const p = payload.data || payload;
          const orderId = p.orderId || payload.orderId;
          const status = p.status || payload.status;
          const completedAtIso = p.completedAtIso || payload.completedAtIso;
          const cancelledAtIso = p.cancelledAtIso || payload.cancelledAtIso;
          const cancelReason = p.cancelReason || payload.cancelReason || p.reason;
          if (orderId) {
            const ord = findOrderById(orderId);
            if (ord && ord.status !== status) {
              ord.status = status;
              if (completedAtIso) ord.completedAtIso = completedAtIso;
              if (cancelledAtIso) ord.cancelledAtIso = cancelledAtIso;
              if (cancelReason) ord.cancelReason = cancelReason;
              stateChanged = true;
              playAudioChime(620, 0.15);
              showSmsToast("🔄 CẬP NHẬT TRẠNG THÁI ĐƠN!", `Đơn #${orderId} đã chuyển sang: ${getStatusBadgeText(status)}`);
            }
          }
          if (Array.isArray(payload.menuStock)) {
            mergeMenuStock(payload.menuStock);
          }
          break;
        }

        case 'ORDER_DISPATCH': {
          const p = payload.data || payload;
          const orderId = p.orderId || payload.orderId;
          const deliveryPartner = p.deliveryPartner || payload.deliveryPartner;
          const deliveryPartnerName = p.deliveryPartnerName || payload.deliveryPartnerName;
          const trackingCode = p.trackingCode || payload.trackingCode;
          const driver = p.driver || payload.driver;
          if (orderId) {
            const ord = findOrderById(orderId);
            if (ord) {
              if (deliveryPartner) ord.deliveryPartner = deliveryPartner;
              if (deliveryPartnerName) ord.deliveryPartnerName = deliveryPartnerName;
              if (trackingCode) ord.trackingCode = trackingCode;
              if (driver) ord.driver = driver;
              ord.deliveryStatus = 'assigned';
              stateChanged = true;
              showSmsToast("🛵 ĐÃ ĐIỀU PHỐI TÀI XẾ!", `Đơn #${orderId} đã gán tài xế ${driver?.name || 'Giao hàng'}.`);
            }
          }
          break;
        }

        case 'ORDER_DELETE': {
          if (payload.orderId) {
            orders = orders.filter(o => o.id !== payload.orderId);
            stateChanged = true;
            showSmsToast("🗑️ ĐÃ XÓA ĐƠN", `Đơn #${payload.orderId} đã bị xóa trên máy khác.`);
          }
          break;
        }

        case 'ORDERS_SYNC': {
          if (Array.isArray(payload.orders)) {
            payload.orders.forEach(co => {
              const idx = orders.findIndex(o => o.id === co.id);
              if (idx === -1) orders.unshift(co);
              else orders[idx] = { ...orders[idx], ...co };
            });
            stateChanged = true;
          }
          break;
        }

        case 'HANDSHAKE': {
          console.log('[Render Handshake] 🤝 Đã nhận toàn bộ dữ liệu mới nhất từ Render Cloud!');
          if (payload.codeVersion) {
            if (window.__posCodeVersion && window.__posCodeVersion !== payload.codeVersion) {
              window.location.reload(true);
              return;
            }
            window.__posCodeVersion = payload.codeVersion;
          }
          if (Array.isArray(payload.menu) && payload.menu.length > 0) {
            menu = mergeMenuWithServer(payload.menu);
          }
          if (payload.config && typeof payload.config === 'object') {
            storeConfig = { ...storeConfig, ...payload.config };
          if (!storeConfig.banner || !Array.isArray(storeConfig.banner.images) || storeConfig.banner.images.length === 0) {
            if (!storeConfig.banner) storeConfig.banner = {};
            storeConfig.banner.images = [...DEFAULT_BANNER_PRESETS];
          }
          }
          if (Array.isArray(payload.discounts) && payload.discounts.length > 0) {
            discounts = payload.discounts;
            saveLocalDiscounts();
          }
          if (Array.isArray(payload.orders)) {
            orders = payload.orders;
          }
          saveLocalData();
          renderCustomerProducts();
          renderFrontendBanner();
          sanitizeOrdersData();
          renderAdminMenuTable();
          renderAdminDiscountsTable();
          renderBackendConfig();
          renderCustomerFooterInfo();
          renderAllBackendTabs();
          updateCloudSyncIndicator('🟢 Render Cloud: Live', true);
          break;
        }

        case 'CODE_UPDATE': {
          console.log('⚡ [POS Hot-Reload] Máy chủ cập nhật mã nguồn mới! Tự động nạp lại...');
          setTimeout(() => { window.location.reload(true); }, 500);
          break;
        }

        case 'MENU_UPDATE': {
          const freshMenu = payload.menu || payload.data;
          if (Array.isArray(freshMenu) && freshMenu.length > 0) {
            menu = mergeMenuWithServer(freshMenu);
            saveLocalData();
            stateChanged = true;
            renderCustomerProducts();
            renderAdminMenuTable();
            console.log("[Sync] Thực đơn, giá & hình ảnh đã đồng bộ từ Render.");
          }
          break;
        }

        case 'DISCOUNTS_UPDATE': {
          const freshDiscounts = payload.discounts || payload.data;
          if (Array.isArray(freshDiscounts)) {
            discounts = freshDiscounts;
            stateChanged = true;
            saveLocalDiscounts();
            renderAdminDiscountsTable();
            console.log("[Sync] Danh sách mã ưu đãi đã được đồng bộ.");
          }
          break;
        }

        case 'CONFIG_UPDATE': {
          const freshConfig = payload.config || payload.data;
          if (freshConfig && typeof freshConfig === 'object') {
            storeConfig = { ...storeConfig, ...freshConfig };
            saveLocalData();
            stateChanged = true;
            renderBackendConfig();
            renderCustomerFooterInfo();
            console.log("[Sync] Cấu hình quán đã được đồng bộ.");
          }
          break;
        }

                case 'FULL_SYNC':
        case 'RESPONSE_FULL_SYNC': {
          const pData = payload.data || payload;
          if (pData.codeVersion) {
            if (window.__posCodeVersion && window.__posCodeVersion !== pData.codeVersion) {
              window.location.reload(true);
              return;
            }
            window.__posCodeVersion = pData.codeVersion;
          }

          let menuChanged = false;
          let ordersChanged = false;
          let discountsChanged = false;
          let configChanged = false;

          // 1. Kiểm tra đơn hàng: Chỉ cập nhật khi ordersVersion thay đổi hoặc lần đầu nạp
          if (Array.isArray(pData.orders)) {
            if (!lastOrdersVersion || (pData.ordersVersion && pData.ordersVersion !== lastOrdersVersion) || !isInitialLoadDone) {
              orders = pData.orders;
              lastOrdersVersion = pData.ordersVersion || Date.now();
              ordersChanged = true;
            }
          }

          // 2. Kiểm tra thực đơn: Chỉ vẽ lại món khi menuVersion thay đổi (tránh re-render lúc khách lướt web)
          if (Array.isArray(pData.menu) && pData.menu.length > 0) {
            menu = mergeMenuWithServer(pData.menu);
            lastMenuVersion = pData.menuVersion || Date.now();
            menuChanged = true;
          }

          // 3. Khuyến mãi & Cấu hình
          if (Array.isArray(pData.discounts)) {
            if (!lastDiscountsVersion || (pData.discountsVersion && pData.discountsVersion !== lastDiscountsVersion)) {
              discounts = pData.discounts;
              lastDiscountsVersion = pData.discountsVersion || Date.now();
              saveLocalDiscounts();
              discountsChanged = true;
            }
          }
          if (pData.config && typeof pData.config === 'object') {
            if (!lastConfigVersion || (pData.configVersion && pData.configVersion !== lastConfigVersion)) {
              storeConfig = { ...storeConfig, ...pData.config };
              if (!storeConfig.banner || !Array.isArray(storeConfig.banner.images) || storeConfig.banner.images.length === 0) {
                if (!storeConfig.banner) storeConfig.banner = {};
                storeConfig.banner.images = [...DEFAULT_BANNER_PRESETS];
              }
              lastConfigVersion = pData.configVersion || Date.now();
              configChanged = true;
            }
          }

          // CHỈ THỰC HIỆN VẼ LẠI GIAO DIỆN (DOM) CHO PHẦN THỰC SỰ THAY ĐỔI
          if (menuChanged) {
            saveLocalData();
            renderCustomerProducts();
            renderFrontendBanner();
            sanitizeOrdersData();
            renderAdminMenuTable();
          }
          if (ordersChanged) {
            saveLocalData();
            renderAllBackendTabs();
            updateCartBadge();
            const trackingModal = document.getElementById('order-tracking-modal');
            if (trackingModal && trackingModal.style.display === 'flex') {
              const curTrackId = document.getElementById('tracking-input-order-id')?.value?.trim();
              if (curTrackId) renderLiveTrackingInfo(curTrackId, false);
            }
          }
          if (discountsChanged) {
            renderAdminDiscountsTable();
          }
          if (configChanged) {
            saveLocalData();
            renderBackendConfig();
            renderCustomerFooterInfo();
          }

          isInitialLoadDone = true;
          break;
        }
      }

      if (stateChanged) {
        saveLocalData();
        renderAllBackendTabs();
        updateCartBadge();
        const trackingModal = document.getElementById('order-tracking-modal');
        if (trackingModal && trackingModal.style.display === 'flex') {
          const curTrackId = document.getElementById('tracking-input-order-id')?.value?.trim();
          if (curTrackId) renderLiveTrackingInfo(curTrackId, false);
        }
        updateCloudSyncIndicator('🟢 Đã đồng bộ lúc ' + new Date().toLocaleTimeString('vi-VN'), true);
      }
    }

    // ==================== PHÁT SỰ KIỆN LÊN RENDER CLOUD POS ====================
    function broadcastMeshEvent(type, data = {}) {
      const envelope = {
        type: type,
        senderId: LOCAL_DEVICE_ID,
        timestamp: Date.now(),
        ...data
      };

      // 1. WebSocket tới Render (Realtime <50ms)
      if (wsClient && wsClient.readyState === 1) {
        try { wsClient.send(JSON.stringify(envelope)); } catch(e) {}
      }

      // 2. HTTP POST tới Render
      pushToLocalServerSync(type, data);

      // 3. Local BroadcastChannel
      if (localTabBroadcast) {
        try { localTabBroadcast.postMessage(envelope); } catch(e) {}
      }

      updateCloudSyncIndicator('🟢 Đã đồng bộ lúc ' + new Date().toLocaleTimeString('vi-VN'), true);
    }

    function pushToLocalServerSync(type, data) {
      if (type === 'NEW_ORDER' && data.order) {
        fetch('/api/orders', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data.order)
        }).catch(() => {});
      } else if (type === 'ORDER_STATUS' && data.orderId) {
        fetch(`/api/orders/${data.orderId}/status`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status: data.status, reason: data.cancelReason })
        }).catch(() => {});
      } else if (type === 'MENU_UPDATE' && data.menu) {
        fetch('/api/menu', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data.menu)
        }).catch(() => {});
      } else if (type === 'CONFIG_UPDATE' && data.config) {
        fetch('/api/config', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data.config)
        }).catch(() => {});
      } else if (type === 'DISCOUNTS_UPDATE' && data.discounts) {
        fetch('/api/discounts', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data.discounts)
        }).catch(() => {});
      }

      fetch('/api/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          orders: sanitizeOrdersForMesh(orders),
          menu: menu,
          discounts: discounts,
          config: storeConfig
        })
      }).catch(() => {});
    }

    function pushOrdersToCloud(ordersToSync) {
      broadcastMeshEvent('ORDERS_SYNC', { orders: sanitizeOrdersForMesh(ordersToSync) });
    }

    function pullOrdersFromCloud() {
      pullFullSyncFromServer();
    }

    function pushMenuToCloud(menuData) {
      broadcastMeshEvent('MENU_UPDATE', { menu: menuData });
    }

    function pullMenuFromCloud() {
      pullFullSyncFromServer();
    }

    function initRealtimeCloudMesh() {
      initWebSocketSync();
      initLocalTabSync();
      pullFullSyncFromServer();

      if (pollIntervalTimer) clearInterval(pollIntervalTimer);
      pollIntervalTimer = setInterval(pullFullSyncFromServer, 3500);

      console.log('🚀 [Render Cloud POS] Khởi chạy engine đồng bộ trực tiếp tới Render Cloud!');
    }

