    // ==================== TIỆN ÍCH SAO CHÉP CHUẨN IOS ====================
    function copyToClipboard(text, msg) {
      if (!text) return;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(() => {
          showSmsToast("📋 ĐÃ SAO CHÉP!", msg || "Đã lưu vào bộ nhớ tạm.");
        }).catch(() => {
          fallbackCopyText(text, msg);
        });
      } else {
        fallbackCopyText(text, msg);
      }
    }
    function fallbackCopyText(text, msg) {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand('copy');
        showSmsToast("📋 ĐÃ SAO CHÉP!", msg || "Đã lưu vào bộ nhớ tạm.");
      } catch (e) {}
      document.body.removeChild(ta);
    }
    window.copyToClipboard = copyToClipboard;

function formatMoney(amount) {
      if (typeof amount !== 'number') amount = Number(amount) || 0;
      return new Intl.NumberFormat('vi-VN').format(amount) + ' đ';
    }

    function showSmsToast(title, message) {
      const toast = document.getElementById('sms-toast');
      if (!toast) return;
      const tTitle = document.getElementById('sms-toast-title');
      const tBody = document.getElementById('sms-toast-body');
      if (tTitle) tTitle.textContent = title;
      if (tBody) tBody.textContent = message;
      toast.classList.add('show');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        toast.classList.remove('show');
      }, 4500);
    }

    let globalAudioCtx = null;
