    function getAudioContext() {
      try {
        if (!globalAudioCtx) {
          const AudioContextClass = window.AudioContext || window.webkitAudioContext;
          if (AudioContextClass) globalAudioCtx = new AudioContextClass();
        }
        if (globalAudioCtx && globalAudioCtx.state === 'suspended') {
          globalAudioCtx.resume().catch(() => {});
        }
        return globalAudioCtx;
      } catch (e) {
        return null;
      }
    }

    function unlockAudioContextOnGesture() {
      const ctx = getAudioContext();
      if (ctx && ctx.state === 'suspended') {
        ctx.resume().catch(() => {});
      }
    }
    ['click', 'touchstart', 'keydown'].forEach(evt => {
      window.addEventListener(evt, unlockAudioContextOnGesture, { passive: true });
    });

    function playAudioChime(freq, duration) {
      try {
        const audioCtx = getAudioContext();
        if (!audioCtx) return;
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq || 650, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.15, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + (duration || 0.12));
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + (duration || 0.12));
      } catch(e) {}
    }

    function playSuccessChime() {
      playAudioChime(523.25, 0.08);
      setTimeout(() => playAudioChime(659.25, 0.1), 80);
      setTimeout(() => playAudioChime(783.99, 0.2), 160);
    }

    
