    function calculateShippingFees(distKm) {
      const dist = (typeof distKm === 'number' && !isNaN(distKm)) ? distKm : 1.8;
      const ahaBaseDist = 4, ahaBaseFee = 18000, ahaPerKm = 5000;
      const lalaBaseDist = 3, lalaBaseFee = 16000, lalaPerKm = 5500;
      
      let feeAha = ahaBaseFee;
      if (dist > ahaBaseDist) {
        feeAha += Math.round((dist - ahaBaseDist) * ahaPerKm);
      }
      
      let feeLala = lalaBaseFee;
      if (dist > lalaBaseDist) {
        feeLala += Math.round((dist - lalaBaseDist) * lalaPerKm);
      }
      
      return { feeAhamove: feeAha, feeLalamove: feeLala };
    }

    function getSelectedShippingFee() {
      return (selectedDeliveryPartner === 'lalamove') ? currentShippingFeeLalamove : currentShippingFeeAhamove;
    }

    function compressImageFile(file, maxWidth, quality, callback) {
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(e) {
        const img = new Image();
        img.onload = function() {
          const canvas = document.createElement('canvas');
          let width = img.width;
          let height = img.height;
          if (width > maxWidth) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
          }
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, width, height);
          const dataUrl = canvas.toDataURL('image/jpeg', quality || 0.85);
          callback(dataUrl);
        };
        img.src = e.target.result;
      };
      reader.readAsDataURL(file);
    }

