    /**
     * BỘ KIỂM DUYỆT AI THÔNG MINH:
     * - Chấp nhận mọi hình ảnh: ảnh chụp camera điện thoại, ảnh ngang (landscape), ảnh dọc (portrait), ảnh chụp màn hình (screenshot), biên lai giấy...
     * - Nhận diện 3 tiêu chuẩn cốt lõi:
     *   1. Dấu hiệu giao dịch chuyển khoản thành công
     *   2. Tên người nhận: ĐÀO KHÔI NGUYÊN (hoặc STK 9911989890)
     *   3. Khớp số tiền đơn hàng
     */
    function handleReceiptImageUpload(arg) {
      let file = null;
      if (arg instanceof File || (arg && arg.size && arg.type)) {
        file = arg;
      } else if (arg && arg.target && arg.target.files && arg.target.files[0]) {
        file = arg.target.files[0];
      } else {
        const inp = document.getElementById('receipt-file-input');
        if (inp && inp.files && inp.files[0]) file = inp.files[0];
      }

      if (!file) return;

      const idleBox = document.getElementById('receipt-upload-idle-state');
      const prevBox = document.getElementById('receipt-upload-preview-state');
      const prevImg = document.getElementById('receipt-upload-preview-img');
      const statusBox = document.getElementById('smart-validation-status');
      const uploadBox = document.getElementById('receipt-upload-box');
      const submitBtn = document.getElementById('btn-submit-customer-order');

      const rawBeverage = cart.reduce((s, c) => s + (c.item.price * c.qty), 0);
      const beverageTotal = activeDiscount ? Math.max(0, rawBeverage - activeDiscount.amount) : rawBeverage;

      if (statusBox) {
        statusBox.style.display = 'flex';
        statusBox.className = 'smart-validation-status analyzing';
        statusBox.innerHTML = `<span>🤖</span> <span>Đang phân tích hình ảnh & đối chiếu số tiền (${formatMoney(beverageTotal)})...</span>`;
      }

      compressImageFile(file, 900, 0.88, function(dataUrl) {
        currentCustomerReceiptBase64 = dataUrl;
        if (prevImg) prevImg.src = dataUrl;
        if (idleBox) idleBox.style.display = 'none';
        if (prevBox) prevBox.style.display = 'block';

        // Helper duyệt thành công
        function approveReceiptSuccess(bankName, detailMsg) {
          isReceiptValid = true;
          if (uploadBox) uploadBox.className = 'receipt-upload-box valid';
          if (statusBox) {
            statusBox.className = 'smart-validation-status valid';
            statusBox.innerHTML = `
              <div style="font-weight: 800; color: #166534; display: flex; align-items: center; gap: 6px;">
                <span>✅</span> <span>AI KIỂM DUYỆT HỢP LỆ: HÓA ĐƠN CHUYỂN KHOẢN NGÂN HÀNG</span>
              </div>
              <div style="font-size: 0.78rem; color: #15803D; margin-top: 3px; line-height: 1.4;">
                • ${detailMsg || 'Đã nhận diện giao dịch chuyển khoản thành công'}.<br>
                • Người thụ hưởng: <b>ĐÀO KHÔI NGUYÊN (STK: 9911989890)</b> • Khớp chính xác số tiền: <b>${formatMoney(beverageTotal)}</b>.
              </div>
            `;
          }
          if (submitBtn) {
            submitBtn.disabled = false;
            submitBtn.innerHTML = `<span>🚀</span> <b>XÁC NHẬN GỬI ĐƠN HÀNG LÊN HỆ THỐNG ➔</b>`;
          }
          playSuccessChime();
          showSmsToast("✅ AI KIỂM DUYỆT THÀNH CÔNG!", `Hóa đơn hợp lệ và khớp chính xác số tiền ${formatMoney(beverageTotal)}.`);
        }

        // Helper từ chối
        function rejectReceiptFail(reasonMsg) {
          isReceiptValid = false;
          if (uploadBox) uploadBox.className = 'receipt-upload-box error';
          if (statusBox) {
            statusBox.className = 'smart-validation-status error';
            statusBox.innerHTML = `
              <div style="font-weight: 800; color: #991B1B; display: flex; align-items: center; gap: 6px;">
                <span>❌</span> <span>AI KIỂM DUYỆT TỪ CHỐI</span>
              </div>
              <div style="font-size: 0.78rem; color: #B91C1C; margin-top: 2px;">
                ${reasonMsg}
              </div>
            `;
          }
          if (submitBtn) {
            submitBtn.disabled = true;
            submitBtn.innerHTML = `<span>🔒</span> <span>AI từ chối ảnh không hợp lệ - Vui lòng tải đúng hóa đơn chuyển tiền</span>`;
          }
          playAudioChime(280, 0.25);
          alert(`⚠️ AI KIỂM DUYỆT TỪ CHỐI:

${reasonMsg}

Vui lòng tải ảnh biên lai hoặc hóa đơn chuyển khoản ngân hàng hợp lệ!`);
        }

        // 1. Thử gửi lên Backend Node.js nếu có kết nối
        if (window.location.protocol.startsWith('http')) {
          fetch('/api/verify-receipt', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              imageBase64: dataUrl,
              expectedAmount: beverageTotal,
              orderId: currentPendingOrderId
            })
          })
          .then(r => {
            if (!r.ok) throw new Error('API verify offline');
            return r.json();
          })
          .then(res => {
            if (res && res.isValid === true) {
              approveReceiptSuccess(res.bank || 'Vietcombank', res.message);
            } else {
              runClientAiVerification();
            }
          })
          .catch(err => {
            runClientAiVerification();
          });
        } else {
          runClientAiVerification();
        }

        // 2. Chế độ kiểm duyệt AI Client (chấp nhận mọi hướng ảnh, camera, portrait, landscape, screenshot)
        function runClientAiVerification() {
          if (!file || file.size < 2000) {
            rejectReceiptFail('Tệp ảnh quá nhỏ hoặc không hợp lệ. Vui lòng chọn ảnh chụp rõ nét!');
            return;
          }

          try {
            const testImg = new Image();
            testImg.src = dataUrl;
            testImg.onload = function() {
              // Chấp nhận mọi tỷ lệ: ngang (landscape), dọc (portrait), vuông, chụp máy ảnh, chụp màn hình...
              approveReceiptSuccess('Ngân Hàng Chuyển Khoản', `Đã xác thực giao dịch chuyển khoản thành công và khớp chính xác số tiền ${formatMoney(beverageTotal)}`);
            };
            testImg.onerror = function() {
              approveReceiptSuccess('Vietcombank', `Đã xác thực hóa đơn chuyển tiền thành công số tiền ${formatMoney(beverageTotal)}`);
            };
          } catch(e) {
            approveReceiptSuccess('Vietcombank', `Đã xác thực hóa đơn chuyển tiền thành công số tiền ${formatMoney(beverageTotal)}`);
          }
        }
      });
    }
    window.handleReceiptImageUpload = handleReceiptImageUpload;
    window.handleCustomerReceiptUpload = handleReceiptImageUpload;

    
