    // ==================== THEO DÕI ĐƠN HÀNG TRỰC TIẾP (LIVE TRACKING) ====================
    function openOrderTrackingModal(orderId) {
      const modal = document.getElementById('order-tracking-modal');
      if (!modal) return;
      modal.style.display = 'flex';

      const targetId = orderId || localStorage.getItem('duynh_latest_order_id') || (orders[0] ? orders[0].id : 'ORD-1001');
      const input = document.getElementById('tracking-input-order-id');
      if (input) input.value = targetId;

      renderLiveTrackingInfo(targetId, false);
    }

    function closeOrderTrackingModal() {
      const modal = document.getElementById('order-tracking-modal');
      if (modal) modal.style.display = 'none';
    }

    function searchAndTrackOrder() {
      const input = document.getElementById('tracking-input-order-id');
      const val = input ? input.value.trim().toUpperCase() : '';
      if (!val) {
        alert("Vui lòng nhập mã đơn hàng (Ví dụ: ORD-1001)!");
        return;
      }
      renderLiveTrackingInfo(val, true);
    }

    function renderLiveTrackingInfo(orderId, showToastAlert = false) {
      const order = findOrderById(orderId);
      if (!order) {
        if (showToastAlert) {
          alert("Không tìm thấy đơn hàng \"" + orderId + "\" trong hệ thống! Vui lòng kiểm tra lại.");
        }
        return;
      }

      const idLabel = document.getElementById('track-order-id-label');
      const badgeEl = document.getElementById('track-order-status-badge');
      const custEl = document.getElementById('track-order-customer');
      const phoneEl = document.getElementById('track-order-phone');
      const addrEl = document.getElementById('track-order-address');
      const partnerEl = document.getElementById('track-order-partner');
      const bevEl = document.getElementById('track-order-beverage');
      const shipEl = document.getElementById('track-order-ship');

      if (idLabel) idLabel.textContent = order.id;
      if (custEl) custEl.textContent = order.customerName || 'Khách Đuỷnh';
      if (phoneEl) phoneEl.textContent = order.phone || '--';
      if (addrEl) addrEl.textContent = order.deliveryAddress || '--';
      if (partnerEl) partnerEl.textContent = order.deliveryPartnerName || 'Ahamove Siêu Tốc';
      if (bevEl) bevEl.textContent = formatMoney(order.beverageTotal || order.total);
      if (shipEl) shipEl.textContent = formatMoney(order.shippingFee || 18000);

      let statusText = '1. Đơn Mới (Đã Nhận)';
      let statusBg = '#FEF3C7', statusColor = '#92400E';
      if (order.status === 'prep') {
        statusText = '2. Đang Pha Chế';
        statusBg = '#E0F2FE'; statusColor = '#0369A1';
      } else if (order.status === 'done' || order.deliveryStatus === 'delivered') {
        statusText = '4. Đã Giao Thành Công';
        statusBg = '#DCFCE7'; statusColor = '#15803D';
      } else if (order.status === 'cancelled') {
        statusText = '❌ Đã Hủy';
        statusBg = '#FEE2E2'; statusColor = '#B91C1C';
      }

      if (badgeEl) {
        badgeEl.textContent = statusText;
        badgeEl.style.background = statusBg;
        badgeEl.style.color = statusColor;
      }

      const s1 = document.getElementById('step-1-received');
      const s2 = document.getElementById('step-2-prep');
      const s3 = document.getElementById('step-3-shipping');
      const s4 = document.getElementById('step-4-delivered');
      const driverBox = document.getElementById('step-3-driver-info');

      [s1, s2, s3, s4].forEach(s => {
        if (s) {
          s.classList.remove('done', 'active');
        }
      });

      if (order.status === 'new') {
        if (s1) s1.classList.add('done');
        if (s2) s2.classList.add('active');
      } else if (order.status === 'prep') {
        if (s1) s1.classList.add('done');
        if (s2) s2.classList.add('done');
        if (s3) s3.classList.add('active');
      } else if (order.status === 'done') {
        if (s1) s1.classList.add('done');
        if (s2) s2.classList.add('done');
        if (s3) s3.classList.add('done');
        if (s4) s4.classList.add('done');
      }

      if (order.trackingCode && driverBox) {
        driverBox.style.display = 'block';
        driverBox.innerHTML = `
          <div style="font-weight: 800; color: #C2410C;">🛵 ` + (order.deliveryPartnerName || 'Shipper') + ` • Mã vận đơn: ` + order.trackingCode + `</div>
          <div>Tài xế: <b>` + (order.driver?.name || 'Nguyễn Văn Hùng') + `</b> • SĐT: <a href="tel:` + (order.driver?.phone || '0903124556') + `" style="color: #0284C7; font-weight:700;">` + (order.driver?.phone || '0903 124 556') + `</a> • 🏍️ ` + (order.driver?.vehicle || 'Wave Alpha') + `</div>
        `;
      } else if (driverBox) {
        driverBox.style.display = 'none';
      }

      if (showToastAlert) {
        showSmsToast("🔍 CẬP NHẬT ĐƠN HÀNG", "Mã đơn #" + order.id + ": " + statusText);
      }
    }


