    // MUA NGAY TRỰC TIẾP TRÊN THẺ MÓN (BỎ QUA CHỌN MÓN NẾU MUỐN NHANH)
    function quickBuyProductNow(itemId) {
      const item = menu.find(m => m.id === itemId);
      if (!item) {
        alert("Không tìm thấy thông tin món ăn!");
        return;
      }
      const isOutOfStock = (item.isAvailable === false || (item.stock !== undefined && item.stock <= 0));
      if (isOutOfStock) {
        alert(`Món "${item.name}" hiện đang tạm hết hàng!`);
        return;
      }
      // Thêm món vào giỏ hàng
      const exIdx = cart.findIndex(c => c.item.id === item.id && (!c.toppings || c.toppings.length === 0));
      if (exIdx !== -1) {
        cart[exIdx].qty += 1;
      } else {
        cart.push({
          item: { ...item },
          qty: 1,
          ice: '100%',
          sugar: '100%',
          toppings: [],
          custom: 'Mặc định (100% Đá • 100% Đường)'
        });
      }
      saveLocalData();
      updateCartBadge();
      updateFloatingCartBar();
      playSuccessChime();
      showSmsToast("⚡ MUA NGAY", `Đã thêm "${item.name}" và mở thanh toán.`);
      
      // Đóng drawer giỏ hàng nếu đang mở
      closeCartDrawer();
      // Mở modal thanh toán
      openPaymentCheckoutModal();
    }
    window.quickBuyProductNow = quickBuyProductNow;
    window.quickBuyProductNow = quickBuyProductNow;

