    // CARD ĐƠN MỚI CÓ BILL (TAB 1 - HIỆU ỨNG CHỚP CHỚP NỔI BẬT DỄ NHẬN DIỆN)
        // HÀM ĐỊNH DẠNG ĐẾM GIÂY KHÁCH CHỜ THEO THỜI GIAN THỰC (TỪNG GIÂY)
    function formatWaitSeconds(createdAt) {
      if (!createdAt) return '0 giây';
      const start = new Date(createdAt).getTime();
      if (isNaN(start)) return '0 giây';
      const diffSec = Math.max(0, Math.floor((Date.now() - start) / 1000));
      const min = Math.floor(diffSec / 60);
      const sec = diffSec % 60;
      if (min === 0) {
        return `${sec} giây`;
      } else {
        return `${min}p ${sec < 10 ? '0' + sec : sec}s`;
      }
    }
    window.formatWaitSeconds = formatWaitSeconds;

    function startLiveWaitTimerTicker() {
      if (window.liveWaitTimerInterval) clearInterval(window.liveWaitTimerInterval);
      window.liveWaitTimerInterval = setInterval(() => {
        const timerElements = document.querySelectorAll('.live-wait-timer');
        if (timerElements.length > 0) {
          timerElements.forEach(el => {
            const timeStr = el.getAttribute('data-time');
            if (timeStr) {
              el.textContent = formatWaitSeconds(timeStr);
            }
          });
        }
      }, 1000);
    }
    window.startLiveWaitTimerTicker = startLiveWaitTimerTicker;

    // HỦY ĐƠN HÀNG TRỰC TIẾP & DỨT ĐIỂM (KHÔNG BỊ MẮC KẸT TRÊN GIAO DIỆN)
    // =========================================================================
    // 🛡️ HỦY ĐƠN HÀNG TRỰC TIẾP & DỨT ĐIỂM (100% HOẠT ĐỘNG, KHÔNG PHỤ THUỘC POPUP TRÌNH DUYỆT)
    // =========================================================================
    function cancelOrderDirectly(orderId, reason = 'Khách yêu cầu hủy') {
      if (!orderId) return false;
      const clean = String(orderId).trim().toUpperCase();
      const digits = clean.replace(/\D/g, '');

      // Tìm kiếm đơn linh hoạt tối đa: ORD-1006, 1006, chữ số
      let order = orders.find(o => {
        if (!o || !o.id) return false;
        const oId = String(o.id).trim().toUpperCase();
        if (oId === clean) return true;
        if (oId === 'ORD-' + clean) return true;
        if ('ORD-' + oId === clean) return true;
        if (digits && oId.replace(/\D/g, '') === digits) return true;
        return false;
      });

      if (!order) {
        console.warn("Không tìm thấy đơn hàng #" + orderId + ", tạo bản ghi hủy cưỡng bức để xóa sạch");
        order = {
          id: clean.startsWith('ORD-') ? clean : ('ORD-' + (digits || clean)),
          status: 'cancelled',
          customerName: 'Đơn ' + clean,
          total: 0
        };
        orders.unshift(order);
      }

      const canonicalId = order.id;
      order.status = 'cancelled';
      order.cancelReason = reason;
      order.cancelledAtIso = new Date().toISOString();

      // Hoàn lại tồn kho
      if (Array.isArray(order.items)) {
        order.items.forEach(ci => {
          const m = menu.find(it => it.id === ci.id || it.name === ci.name);
          if (m && m.stock !== undefined) {
            m.stock += (ci.qty || 1);
            m.isAvailable = true;
          }
        });
      }

      saveLocalData();
      renderAllBackendTabs();

      try {
        broadcastMeshEvent('ORDER_STATUS', { 
          orderId: canonicalId, 
          status: 'cancelled', 
          cancelReason: reason, 
          cancelledAtIso: order.cancelledAtIso, 
          menuStock: menu 
        });
      } catch(e) {}

      fetch(`/api/orders/${canonicalId}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'cancelled', reason })
      }).catch(() => {});

      playAudioChime(420, 0.18);
      showSmsToast("❌ ĐÃ HỦY ĐƠN HÀNG #" + canonicalId, "Đơn đã được xóa ngay lập tức khỏi danh sách chờ duyệt!");
      return true;
    }
    window.cancelOrderDirectly = cancelOrderDirectly;

